            self.assertIn(["/x/claude", "stop", "5e551011"], calls)  # it was running: stopped first
            self.assertEqual(calls[-1][:4], ["/x/claude", "--bg", "--permission-mode", "plan"])  # a copy, in plan mode
            self.assertIn("--resume=5e551011-aaaa-bbbb", calls[-1])
